'function reenviarWhatsApp(idConfig, numPed) {',
unistr('  customConfirm(''\D83D\DCF1 Reenviar alerta por <strong>WhatsApp</strong> para o pedido <strong>'' + numPed + ''</strong>?'', function() {'),
