wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(21404211137130552997)
,p_plug_name=>'R_KANBAN'
,p_static_id=>'r-kanban'
,p_title=>'KANBAN'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>90
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  CURSOR c_col IS',
'    SELECT ''Aguardando Carregamento'' status, ''#FEF6D8'' bg_head, ''#7a5c00'' cor_head, ''#E8B923'' cor_borda FROM dual UNION ALL',
unistr('    SELECT ''Sem Ve\00EDculo Alocado'',''#F4ECF7'',''#7D3C98'',''#A569BD'' FROM dual UNION ALL'),
unistr('    SELECT ''Em Tr\00E2nsito'',''#EAF1F8'',''#2C5F8A'',''#2C5F8A'' FROM dual UNION ALL'),
'    SELECT ''Atrasado'',''#FCEBEB'',''#791F1F'',''#A32D2D'' FROM dual UNION ALL',
'    SELECT ''Entregue'',''#E6F4EA'',''#1E7B45'',''#1E7B45'' FROM dual UNION ALL',
'    SELECT ''Cancelada'',''#F9F0F0'',''#7F7F7F'',''#C9C9C9'' FROM dual;',
'  v_qtd NUMBER;',
'  v_html CLOB := '''';',
'BEGIN',
'  v_html := v_html || ''<div style="display:flex; gap:12px; align-items:flex-start;">'';',
'  FOR col IN c_col LOOP',
'    SELECT COUNT(*) INTO v_qtd FROM vw_jornada_carga WHERE status_oc = col.status;',
'    v_html := v_html || ''<div style="flex:1; min-width:0; background:#f7f7f5; border-radius:10px; overflow:hidden;">'';',
'',
unistr('    -- CABE\00C7ALHO DA COLUNA (era 12px \2192 14px; contador era 10px \2192 13px)'),
'    v_html := v_html || ''<div style="padding:10px 14px; background:''||col.bg_head||''; color:''||col.cor_head||''; font-size:14px; font-weight:700; display:flex; justify-content:space-between; align-items:center;">'';',
'    v_html := v_html || ''<span>''||col.status||''</span>'';',
'    v_html := v_html || ''<span style="background:''||col.cor_borda||''; color:#fff; border-radius:20px; padding:2px 10px; font-size:13px; font-weight:700;">''||v_qtd||''</span>'';',
'    v_html := v_html || ''</div>'';',
'',
'    v_html := v_html || ''<div style="padding:8px; display:flex; flex-direction:column; gap:8px;">'';',
'',
'    FOR j IN (',
'      SELECT num_ped,',
'             NVL(cliente, ''sem cliente'') cliente,',
'             NVL(produto, ''sem produto'') produto,',
'             NVL(veiculo_placa,''sem veiculo'') placa,',
'             NVL(motorista,''sem motorista'') motorista,',
'             NVL(''R$ ''||TO_CHAR(frete_valor,''FM999G999D00''),''sem frete'') frete',
'      FROM vw_jornada_carga',
'      WHERE status_oc = col.status',
'      ORDER BY num_ped',
'      FETCH FIRST 5 ROWS ONLY',
'    ) LOOP',
'      v_html := v_html || ''<div style="background:#fff; border:0.5px solid #e5e5e0; border-left:3px solid ''||col.cor_borda||''; border-radius:5px; padding:10px 12px;">'';',
'',
unistr('      -- N\00FAmero do pedido (era 12px \2192 14px)'),
'      v_html := v_html || ''<div style="font-size:14px; font-weight:700; color:#2c2c2a; margin-bottom:4px;">Pedido ''||j.num_ped||''</div>'';',
'',
unistr('      -- Cliente (era 11px \2192 13px)'),
'      v_html := v_html || ''<div style="font-size:13px; font-weight:600; color:#3d3d3b; margin-bottom:3px;">''||j.cliente||''</div>'';',
'',
unistr('      -- Produto (era 10px \2192 13px)'),
'      v_html := v_html || ''<div style="font-size:13px; font-weight:500; color:''||col.cor_borda||''; margin-bottom:4px;">''||j.produto||''</div>'';',
'',
unistr('      -- Placa e motorista (era 10px \2192 12px)'),
unistr('      v_html := v_html || ''<div style="font-size:12px; color:#888780; margin-bottom:2px;">''||j.placa||'' \00B7 ''||j.motorista||''</div>'';'),
'',
unistr('      -- Frete (era 10px \2192 12px)'),
'      v_html := v_html || ''<div style="font-size:12px; font-weight:600; color:#61615E;">''||j.frete||''</div>'';',
'',
'      v_html := v_html || ''</div>'';',
'    END LOOP;',
'',
'    IF v_qtd = 0 THEN',
'      v_html := v_html || ''<div style="font-size:13px; color:#b4b2a9; text-align:center; padding:16px 0;">Nenhum pedido</div>'';',
'    END IF;',
'',
'    v_html := v_html || ''</div></div>'';',
'  END LOOP;',
'  v_html := v_html || ''</div>'';',
'  RETURN v_html;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_created_on=>wwv_flow_imp.dz('20260728184810Z')
,p_updated_on=>wwv_flow_imp.dz('20260819112518Z')
,p_created_by=>'MATHEUS.CATENACCI@ARTGROUP.COM.BR'
,p_updated_by=>'MATHEUS'
);
