,p_region_css_classes=>'kpi-artpetro'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
unistr('  ''\26A0\FE0F ATRASADAS'' titulo,'),
'  (SELECT COUNT(*) FROM vw_jornada_carga WHERE status_oc = ''Atrasado'') valor,',
'  ''danger'' cor,',
'  ''alert'' icone,',
'  ''kpi-artpetro kpi-danger'' css_class',
'FROM DUAL',
'UNION ALL SELECT ',
unistr('  ''\D83D\DE9A EM TR\00C2NSITO'','),
unistr('  (SELECT COUNT(*) FROM vw_jornada_carga WHERE status_oc = ''Em Tr\00E2nsito''),'),
'  ''info'', ''arrow-right'',',
'  ''kpi-artpetro kpi-info''',
'FROM DUAL',
'UNION ALL SELECT ',
unistr('  ''\23F3 AGUARDANDO'','),
unistr('  (SELECT COUNT(*) FROM vw_jornada_carga WHERE status_oc IN (''Aguardando Carregamento'', ''Sem Ve\00EDculo Alocado'')),'),
'  ''warning'', ''clock'',',
'  ''kpi-artpetro kpi-warning''',
'FROM DUAL',
'UNION ALL SELECT ',
unistr('  ''\2705 ENTREGUES'','),
'  (SELECT COUNT(*) FROM vw_jornada_carga WHERE status_oc = ''Entregue''),',
'  ''success'', ''check'',',
'  ''kpi-artpetro kpi-success''',
'FROM DUAL',
'UNION ALL SELECT ',
unistr('  ''\2715 CANCELADOS'','),
'  (SELECT COUNT(*) FROM vw_jornada_carga WHERE status_oc = ''Cancelada''),',
'  ''danger'', ''times'',',
'  ''kpi-artpetro kpi-danger''',
'FROM DUAL'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20260803185347Z')
,p_updated_on=>wwv_flow_imp.dz('20260819110926Z')
,p_created_by=>'MATHEUS.CATENACCI@ARTGROUP.COM.BR'
,p_updated_by=>'MATHEUS'
);
