wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(14536185680708792)
,p_process_sequence=>60
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'AJAX_LOG_ALERTAS'
,p_static_id=>'ajax-log-alertas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_html  CLOB := '''';',
'  v_num_ped VARCHAR2(50) := APEX_APPLICATION.G_X01;',
'  v_count NUMBER;',
'BEGIN',
'  SELECT COUNT(*) INTO v_count FROM DAB_ALERTAS WHERE ID_REFERENCIA = v_num_ped;',
'',
'  v_html := ''<div style="padding:4px 0;">'';',
'',
'  IF v_count = 0 THEN',
'    -- ESTADO VAZIO',
'    v_html := v_html || ''<div style="text-align:center; padding:32px; color:#888; font-size:14px;">Nenhum alerta registrado para este pedido.</div>'';',
'  ELSE',
'    FOR r IN (',
'      SELECT',
'        a.ID_ALERTA,',
'        a.ID_CONFIG,',
'        TO_CHAR(a.CRIADO_EM, ''DD/MM/YYYY HH24:MI'') AS DT,',
'        a.TIPO_ALERTA,',
'        a.DESCRICAO,',
'        a.USUARIO,',
'        a.STATUS,',
'        NVL(c.ENVIAR_WHATSAPP, 0) AS ENVIAR_WHATSAPP,',
'        NVL(c.ENVIAR_EMAIL, 0) AS ENVIAR_EMAIL',
'      FROM DAB_ALERTAS a',
'      LEFT JOIN DAB_SISPETRO_ALERTAS_CONFIG c ON c.ID = a.ID_CONFIG',
'      WHERE a.ID_REFERENCIA = v_num_ped',
'      ORDER BY a.CRIADO_EM DESC',
'    ) LOOP',
'',
'      -- COR DA BORDA LATERAL: vermelho se ATIVO, cinza se RESOLVIDO',
'      DECLARE',
'        v_cor_borda VARCHAR2(20);',
'        v_bg        VARCHAR2(20);',
'        v_cor_borda_card VARCHAR2(20);',
'      BEGIN',
'        IF r.STATUS = ''ATIVO'' THEN',
'          v_cor_borda      := ''#A32D2D'';',
'          v_bg             := ''#FFFAFA'';',
'          v_cor_borda_card := ''#F5C6C6'';',
'        ELSE',
'          v_cor_borda      := ''#C9C9C9'';',
'          v_bg             := ''#FAFAFA'';',
'          v_cor_borda_card := ''#E8E8E8'';',
'        END IF;',
'',
'        v_html := v_html || ''<div style="border:1px solid '' || v_cor_borda_card || ''; border-left:4px solid '' || v_cor_borda || ''; border-radius:6px; padding:14px 16px; margin-bottom:10px; background:'' || v_bg || '';">'';',
'',
'        -- HEADER: tipo + badge status',
'        v_html := v_html || ''<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">'';',
'        v_html := v_html || ''<div style="font-size:14px; font-weight:700; color:#2c2c2a;">'' || NVL(r.TIPO_ALERTA, ''ALERTA'') || ''</div>'';',
'',
'        IF r.STATUS = ''ATIVO'' THEN',
unistr('          v_html := v_html || ''<span style="background:#FADBD8; color:#A32D2D; padding:4px 12px; border-radius:20px; font-size:12px; font-weight:700; border:1px solid #A32D2D;">\25CF ATIVO</span>'';'),
'        ELSE',
unistr('          v_html := v_html || ''<span style="background:#F0F0F0; color:#7F7F7F; padding:4px 12px; border-radius:20px; font-size:12px; font-weight:700; border:1px solid #C9C9C9;">\25CB '' || NVL(r.STATUS, ''INATIVO'') || ''</span>'';'),
'        END IF;',
'',
'        v_html := v_html || ''</div>'';',
'',
unistr('        -- DESCRI\00C7\00C3O'),
unistr('        v_html := v_html || ''<div style="font-size:13px; color:#444; margin-bottom:10px; line-height:1.5;">'' || NVL(r.DESCRICAO, ''Sem descri\00E7\00E3o'') || ''</div>'';'),
'',
unistr('        -- DATA E USU\00C1RIO'),
'        v_html := v_html || ''<div style="display:flex; gap:20px; margin-bottom:12px;">'';',
unistr('        v_html := v_html || ''<div style="font-size:13px; color:#7F7F7F;">\D83D\DCC5 '' || r.DT || ''</div>'';'),
unistr('        v_html := v_html || ''<div style="font-size:13px; color:#7F7F7F;">\D83D\DC64 '' || NVL(r.USUARIO, ''Sistema'') || ''</div>'';'),
'        v_html := v_html || ''</div>'';',
'',
unistr('        -- BOT\00D5ES (s\00F3 para ATIVO)'),
'        IF r.STATUS = ''ATIVO'' THEN',
'          v_html := v_html || ''<div style="display:flex; gap:8px; flex-wrap:wrap;">'';',
'',
'          IF r.ENVIAR_WHATSAPP = 1 THEN',
'            v_html := v_html || ''<button onclick="reenviarWhatsApp('' || r.ID_CONFIG || '','''''' || v_num_ped || '''''')" ''',
'                             || ''style="background:#25D366; color:#fff; border:none; border-radius:6px; padding:8px 16px; font-size:13px; font-weight:600; cursor:pointer;">''',
unistr('                             || ''\D83D\DCF1 WhatsApp</button>'';'),
'          END IF;',
'',
'          IF r.ENVIAR_EMAIL = 1 THEN',
'            v_html := v_html || ''<button onclick="reenviarEmail('' || r.ID_CONFIG || '','''''' || v_num_ped || '''''')" ''',
'                             || ''style="background:#E25F21; color:#fff; border:none; border-radius:6px; padding:8px 16px; font-size:13px; font-weight:600; cursor:pointer;">''',
unistr('                             || ''\2709\FE0F Email</button>'';'),
'          END IF;',
'',
'          v_html := v_html || ''<button onclick="resolverAlerta('' || r.ID_ALERTA || '','''''' || v_num_ped || '''''')" ''',
'                           || ''style="background:#27AE60; color:#fff; border:none; border-radius:6px; padding:8px 16px; font-size:13px; font-weight:600; cursor:pointer;">''',
unistr('                           || ''\2705 Resolver</button>'';'),
'',
'          v_html := v_html || ''</div>'';',
'        END IF;',
'',
'        v_html := v_html || ''</div>'';',
'      END;',
'',
'    END LOOP;',
'  END IF;',
'',
'  v_html := v_html || ''</div>'';',
'  HTP.P(v_html);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6889080865147733
,p_created_on=>wwv_flow_imp.dz('20260814154234Z')
,p_updated_on=>wwv_flow_imp.dz('20260819113843Z')
,p_created_by=>'MATHEUS'
,p_updated_by=>'MATHEUS'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(22094620818106534692)
,p_process_sequence=>40
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'AJAX_LOG_PEDIDO'
,p_static_id=>'ajax-log-pedido'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_html      CLOB := '''';',
'  v_num_ped   VARCHAR2(50) := APEX_APPLICATION.G_X01;',
'  v_tipo      VARCHAR2(20);',
'  v_status    VARCHAR2(50);',
'  v_cliente   VARCHAR2(200);',
'  v_produto   VARCHAR2(200);',
'  v_usuario   VARCHAR2(100);',
'  v_oc        VARCHAR2(50);',
'  v_motorista VARCHAR2(200);',
'  v_placa     VARCHAR2(20);',
'  v_status_car VARCHAR2(50);',
'  v_tem_log   NUMBER := 0;',
'BEGIN',
'  -- Dados do PEDIDO',
'  SELECT p.TIPO, p.STATUS_PEDIDO, p.CLIENTE, p.PRODUTO, p.USUARIO_PEDIDO',
'  INTO v_tipo, v_status, v_cliente, v_produto, v_usuario',
'  FROM PEDIDOS p',
'  WHERE p.NUM_PED = v_num_ped AND ROWNUM = 1;',
'',
'  -- Dados CARREGAMENTO',
'  BEGIN',
'    SELECT c.NUMERO_OC, c.MOTORISTA, c.VEICULO_PLACA, c.STATUS_CARREGAMENTO',
'    INTO v_oc, v_motorista, v_placa, v_status_car',
'    FROM CARREGAMENTOS c',
'    JOIN PEDIDOS p ON p.SEQ_PEDIDO = c.FK_SEQ_PEDIDO',
'    WHERE p.NUM_PED = v_num_ped AND ROWNUM = 1;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'    v_oc := NULL; v_motorista := NULL; v_placa := NULL; v_status_car := NULL;',
'  END;',
'',
'  -- ============================================================',
'  -- CARDS SISPETRO + ENGERISCO',
'  -- ============================================================',
'  v_html := ''<div style="display:flex; gap:12px; margin-bottom:16px;">'';',
'',
'  -- SISPETRO',
'  v_html := v_html || ''<div style="flex:1; background:#FFF8F0; border:1px solid #FFD9B3; border-radius:8px; padding:14px;">'';',
'  v_html := v_html || ''<div style="display:inline-block; background:#E25F21; color:#fff; font-size:11px; font-weight:700; padding:3px 10px; border-radius:20px; margin-bottom:12px; letter-spacing:0.5px;">SISPETRO</div>'';',
'  v_html := v_html || ''<div style="font-size:14px; color:#444; margin-bottom:6px;"><b>Pedido:</b> '' || v_num_ped || ''</div>'';',
unistr('  v_html := v_html || ''<div style="font-size:14px; color:#444; margin-bottom:6px;"><b>Tipo:</b> '' || CASE v_tipo WHEN ''C'' THEN ''Compra'' WHEN ''T'' THEN ''Transfer\00EAncia'' WHEN ''VD'' THEN ''Venda'' ELSE NVL(v_tipo, ''N\00E3o informado'') END || ''</div>'';'),
unistr('  v_html := v_html || ''<div style="font-size:14px; color:#444; margin-bottom:6px;"><b>Status:</b> '' || NVL(INITCAP(v_status), ''N\00E3o informado'') || ''</div>'';'),
unistr('  v_html := v_html || ''<div style="font-size:14px; color:#444; margin-bottom:6px;"><b>Cliente:</b> '' || NVL(v_cliente, ''N\00E3o informado'') || ''</div>'';'),
unistr('  v_html := v_html || ''<div style="font-size:14px; color:#444; margin-bottom:6px;"><b>Produto:</b> '' || NVL(v_produto, ''N\00E3o informado'') || ''</div>'';'),
unistr('  v_html := v_html || ''<div style="font-size:14px; color:#444;"><b>Criado por:</b> '' || NVL(v_usuario, ''N\00E3o informado'') || ''</div>'';'),
'  v_html := v_html || ''</div>'';',
'',
'  -- ENGERISCO',
'  v_html := v_html || ''<div style="flex:1; background:#F0F4FF; border:1px solid #B3C9FF; border-radius:8px; padding:14px;">'';',
'  v_html := v_html || ''<div style="display:inline-block; background:#3498DB; color:#fff; font-size:11px; font-weight:700; padding:3px 10px; border-radius:20px; margin-bottom:12px; letter-spacing:0.5px;">ENGERISCO</div>'';',
'  IF v_oc IS NOT NULL THEN',
'    v_html := v_html || ''<div style="font-size:14px; color:#444; margin-bottom:6px;"><b>OC:</b> '' || v_oc || ''</div>'';',
unistr('    v_html := v_html || ''<div style="font-size:14px; color:#444; margin-bottom:6px;"><b>Status:</b> '' || NVL(v_status_car, ''N\00E3o informado'') || ''</div>'';'),
unistr('    v_html := v_html || ''<div style="font-size:14px; color:#444; margin-bottom:6px;"><b>Motorista:</b> '' || NVL(v_motorista, ''N\00E3o informado'') || ''</div>'';'),
unistr('    v_html := v_html || ''<div style="font-size:14px; color:#444;"><b>Placa:</b> '' || NVL(v_placa, ''N\00E3o informado'') || ''</div>'';'),
'  ELSE',
'    v_html := v_html || ''<div style="font-size:14px; color:#888; font-style:italic;">Sem OC gerada para este pedido</div>'';',
'  END IF;',
'  v_html := v_html || ''</div>'';',
'',
'  v_html := v_html || ''</div>'';',
'',
'  -- ============================================================',
unistr('  -- HIST\00D3RICO'),
'  -- ============================================================',
'  SELECT COUNT(*) INTO v_tem_log FROM DAB_LOG_PEDIDO WHERE NUM_PED = v_num_ped;',
'',
unistr('  v_html := v_html || ''<div style="font-size:14px; font-weight:700; color:#2c2c2a; margin-bottom:10px; padding-bottom:6px; border-bottom:2px solid #E25F21;">Hist\00F3rico</div>'';'),
'',
'  IF v_tem_log = 0 THEN',
unistr('    v_html := v_html || ''<div style="font-size:13px; color:#b4b2a9; text-align:center; padding:20px 0;">Nenhum registro no hist\00F3rico</div>'';'),
'  ELSE',
'    v_html := v_html || ''<div style="max-height:250px; overflow-y:auto; border:1px solid #eee; border-radius:8px;">'';',
'    FOR r IN (',
'      SELECT TO_CHAR(DATA_EVENTO, ''DD/MM/YYYY HH24:MI'') AS DT,',
'             USUARIO,',
'             ACAO',
'      FROM DAB_LOG_PEDIDO',
'      WHERE NUM_PED = v_num_ped',
'      ORDER BY DATA_EVENTO DESC',
'    ) LOOP',
'      v_html := v_html || ''<div style="display:flex; align-items:flex-start; gap:12px; padding:10px 14px; border-bottom:1px solid #f3f3f3;">'';',
'      v_html := v_html || ''<div style="min-width:120px; font-size:13px; color:#888; white-space:nowrap;">'' || r.DT || ''</div>'';',
'      v_html := v_html || ''<div style="min-width:110px; font-size:13px; font-weight:600; color:#333;">'' || r.USUARIO || ''</div>'';',
'      v_html := v_html || ''<div style="font-size:13px; color:#555;">'' || r.ACAO || ''</div>'';',
'      v_html := v_html || ''</div>'';',
'    END LOOP;',
'    v_html := v_html || ''</div>'';',
'  END IF;',
'',
'  HTP.P(v_html);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>22081968634004528629
,p_created_on=>wwv_flow_imp.dz('20260731201819Z')
,p_updated_on=>wwv_flow_imp.dz('20260819113518Z')
,p_created_by=>'MATHEUS.CATENACCI@ARTGROUP.COM.BR'
,p_updated_by=>'MATHEUS'
);
