,p_plug_name=>unistr('Cadastro de Usu\00E1rios')
,p_static_id=>unistr('cadastro-de-usu\00E1rios')
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    SEQ_USUARIO,',
'    COD_USUARIO,',
'    NOME || '' '' || SOBRENOME AS NOME_COMPLETO,',
'    LOGIN,',
'    CPF,',
'    EMAIL_NOTIFICACAO,',
'    WHATSAPP_NOTIFICACAO,',
'',
'    -- PERFIL com badge colorido por tipo',
'    CASE (SELECT NOME_PERFIL FROM PERFIS WHERE ID_PERFIL = USUARIOS.ID_PERFIL)',
'      WHEN ''Administrador'' THEN ''<span class="badge-admin">Administrador</span>''',
unistr('      WHEN ''Log\00EDstica''     THEN ''<span class="badge-logistica">Log\00EDstica</span>'''),
'      WHEN ''Faturamento''   THEN ''<span class="badge-faturamento">Faturamento</span>''',
'      WHEN ''Operador''      THEN ''<span class="badge-operador">Operador</span>''',
'      ELSE ''<span class="badge-nao">'' || (SELECT NOME_PERFIL FROM PERFIS WHERE ID_PERFIL = USUARIOS.ID_PERFIL) || ''</span>''',
'    END AS PERFIL,',
'',
'    -- STATUS com badge colorido',
'    CASE WHEN ATIVO = ''S''',
'      THEN ''<span class="badge-ativo">Ativo</span>''',
'      ELSE ''<span class="badge-inativo">Inativo</span>''',
'    END AS STATUS,',
'',
'    -- NOTIFICA com badge colorido',
'    CASE WHEN NOTIFICA = ''S''',
'      THEN ''<span class="badge-sim">Sim</span>''',
unistr('      ELSE ''<span class="badge-nao">N\00E3o</span>'''),
'    END AS NOTIFICA,',
'',
'    TO_CHAR(CREATED_AT, ''DD/MM/YYYY HH24:MI'') AS CRIADO_EM,',
'',
unistr('    -- A\00C7\00C3O \2014 bot\00E3o editar padr\00E3o ArtOne'),
'    ''<a href="f?p=&APP_ID.:6:&SESSION.::NO::P6_SEQ_USUARIO:'' || SEQ_USUARIO || ''" ',
'      style="background:#E25F21;color:#fff;padding:6px 14px;border-radius:6px;font-size:13px;font-weight:600;text-decoration:none;">',
unistr('      \270F\FE0F Editar'),
'    </a>'' AS ACAO',
'',
'FROM USUARIOS',
'ORDER BY NOME, SOBRENOME;'))
