,p_plug_name=>'Gerenciador de Acessos'
,p_static_id=>'gerenciador-de-acessos'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    A.SEQ_ACESSO,',
'    A.SEQ_USUARIO,',
'',
'    -- NOME COMPLETO (texto simples)',
'    U.NOME || '' '' || U.SOBRENOME AS NOME_COMPLETO,',
'',
'    -- FILIAL com badge colorido',
'    CASE A.FILIAL',
'      WHEN ''ArtPetro'' THEN ''<span class="badge-artpetro">ArtPetro</span>''',
'      WHEN ''NutriOil''  THEN ''<span class="badge-nutrioil">NutriOil</span>''',
'      ELSE ''<span class="badge-inativo">'' || A.FILIAL || ''</span>''',
'    END AS FILIAL,',
'',
'    -- TIPO PERFIL com badge colorido',
'    CASE A.TIPO_PERFIL',
'      WHEN ''Administrador'' THEN ''<span class="badge-admin">Administrador</span>''',
unistr('      WHEN ''Log\00EDstica''     THEN ''<span class="badge-logistica">Log\00EDstica</span>'''),
'      WHEN ''Faturamento''   THEN ''<span class="badge-faturamento">Faturamento</span>''',
'      WHEN ''Operador''      THEN ''<span class="badge-operador">Operador</span>''',
'      ELSE ''<span class="badge-inativo">'' || A.TIPO_PERFIL || ''</span>''',
'    END AS TIPO_PERFIL,',
'',
'    -- ATIVO com badge colorido',
'    CASE A.ATIVO',
'      WHEN ''S'' THEN ''<span class="badge-ativo">Ativo</span>''',
'      ELSE ''<span class="badge-inativo">Inativo</span>''',
'    END AS ATIVO,',
'',
unistr('    -- DATA formatada no padr\00E3o brasileiro'),
'    TO_CHAR(A.CREATED_AT, ''DD/MM/YYYY'') AS CRIADO_EM,',
'',
'    A.UPDATED_AT',
'',
'FROM USUARIO_FILIAL_ACESSO A',
'JOIN USUARIOS U ON U.SEQ_USUARIO = A.SEQ_USUARIO',
'WHERE A.SEQ_USUARIO = NVL(:P7_SEQ_USUARIO, A.SEQ_USUARIO)',
'ORDER BY U.NOME, U.SOBRENOME, A.FILIAL, A.TIPO_PERFIL'))
,p_plug_source_type=>'NATIVE_IR'
